      this.root = null;       // #pause-menu 根节点
      this.card = null;       // .pause-card
      this.summaryEl = null;  // 左上摘要
      this.sysEl = null;      // 右上小字（时间/存档状态）
      this.focusables = [];   // 可聚焦按钮（真实 DOM 顺序）
