        node.id = 'pause-menu';
        try { node.className = 'pause-overlay hidden'; } catch { /* 桩 */ }
        try { node.setAttribute('role', 'dialog'); node.setAttribute('aria-modal', 'true'); } catch { /* 桩 */ }
        try { node.setAttribute('aria-label', '暂停菜单'); } catch { /* 桩 */ }
