      if (!root) return this;
      try { root.classList.remove('show'); } catch { /* 桩 */ }
      try { root.classList.add('hidden'); } catch { /* 桩 */ }
      try { root.setAttribute('aria-hidden', 'true'); } catch { /* 桩 */ }
